    margin: 0 -4px 0 8px;
    opacity: .75;
    padding-left: 16px;
    position: relative;
    width: 8px
}

.choices[data-type*=select-multiple] .choices__button:focus,
.choices[data-type*=select-multiple] .choices__button:hover,
.choices[data-type*=text] .choices__button:focus,
.choices[data-type*=text] .choices__button:hover {
    opacity: 1
}

.choices__inner {
    background-color: var(--gk-white);
    border: 1px solid var(--gk-gray-300);
    border-radius: 6px;
    display: inline-block;
    font-size: 14px;
    overflow: hidden;
    padding: .5rem 3rem .5rem 1rem;
    vertical-align: top;
    width: 100%
}

.is-focused .choices__inner,
.is-open .choices__inner {
    border-color: var(--gk-primary)
}

.is-open .choices__inner {
    border-radius: 6px 6px 0 0
}

.is-flipped.is-open .choices__inner {
    border-radius: 0 0 6px 6px
}

.choices__list {
    list-style: none;
    margin: 0;
    padding-left: 0
}

.choices__list--single {
    display: inline-block;
    padding: 0;
    width: 100%
}

[dir=rtl] .choices__list--single {
    padding-left: 16px;
    padding-right: 4px
}

.choices__list--single .choices__item {
    width: 100%
}

.choices__list--multiple {
    display: inline
}

.choices__list--multiple .choices__item {
    background-color: var(--gk-primary);
    border: 1px solid var(--gk-primary);
    border-radius: 20px;
    box-sizing: border-box;
    color: #fff;
    display: inline-block;
    font-size: 12px;
    font-weight: 500;
    margin-bottom: 3.75px;
    margin-right: 3.75px;
    padding: 4px 10px;
    vertical-align: middle;
    word-break: break-all
}

.choices__list--multiple .choices__item[data-deletable] {
    padding-right: 5px
}

[dir=rtl] .choices__list--multiple .choices__item {
    margin-left: 3.75px;
    margin-right: 0
}

.choices__list--multiple .choices__item.is-highlighted {
    background-color: var(--gk-primary-subtle);
    border: 1px solid var(--gk-primary-subtle)
}

.is-disabled .choices__list--multiple .choices__item {
    background-color: var(--gk-gray-300);
    border: 1px solid var(--gk-gray-300)
}

.choices__list--dropdown,
.choices__list[aria-expanded] {
    background-color: var(--gk-white);
    border: 1px solid var(--gk-gray-300);
    border-bottom-left-radius: 6px;
    border-bottom-right-radius: 6px;
    margin-top: -1px;
    overflow: hidden;
    position: absolute;
    top: 100%;
    visibility: hidden;
    width: 100%;
    will-change: visibility;
    word-break: break-all;
    z-index: 1
}

.is-active.choices__list--dropdown,
.is-active.choices__list[aria-expanded] {
    visibility: visible
}

.is-open .choices__list--dropdown,
.is-open .choices__list[aria-expanded] {
    border-color: var(--gk-gray-300)
}

.is-flipped .choices__list--dropdown,
.is-flipped .choices__list[aria-expanded] {
    border-radius: .25rem .25rem 0 0;
    bottom: 100%;
    margin-bottom: -1px;
    margin-top: 0;
    top: auto
}

.choices__list--dropdown .choices__list,
.choices__list[aria-expanded] .choices__list {
    max-height: 300px;
    overflow: auto;
    position: relative;
    -webkit-overflow-scrolling: touch;
    will-change: scroll-position
}

.choices__list--dropdown .choices__item,
.choices__list[aria-expanded] .choices__item {
    font-size: 14px;
    padding: 4px 10px;
    position: relative
}

[dir=rtl] .choices__list--dropdown .choices__item,
[dir=rtl] .choices__list[aria-expanded] .choices__item {
    text-align: right
}

@media (min-width:640px) {

    .choices__list--dropdown .choices__item--selectable:after,
    .choices__list[aria-expanded] .choices__item--selectable:after {
        content: attr(data-select-text);
        font-size: 12px;
        opacity: 0;
        position: absolute;
        right: 10px;
        top: 50%;
        transform: translateY(-50%)
    }

    [dir=rtl] .choices__list--dropdown .choices__item--selectable,
    [dir=rtl] .choices__list[aria-expanded] .choices__item--selectable {
        padding-left: 100px;
        padding-right: 10px;
        text-align: right
    }

    [dir=rtl] .choices__list--dropdown .choices__item--selectable:after,
    [dir=rtl] .choices__list[aria-expanded] .choices__item--selectable:after {
        left: 10px;
        right: auto
    }
}

.choices__list--dropdown .choices__item--selectable.is-highlighted,
.choices__list[aria-expanded] .choices__item--selectable.is-highlighted {
    background-color: var(--gk-gray-200)
}

.choices__list--dropdown .choices__item--selectable.is-highlighted:after,
.choices__list[aria-expanded] .choices__item--selectable.is-highlighted:after {
    opacity: .5
}

.choices__item {
    cursor: default
}

.choices__item--selectable {
    cursor: pointer
}

.choices__item--disabled {
    cursor: not-allowed;
    opacity: .5;
    -webkit-user-select: none;
    -moz-user-select: none;
    user-select: none
}

.choices__heading {
    border-bottom: 1px solid var(--gk-gray-200);
