/* v-marquee */

.v-marquee-wrapper{
  position: relative;
  text-align:center;
  overflow: hidden;
}
.v-marquee-wrapper .v-marquee-container{
  overflow:hidden;
  margin:0 auto !important;
  text-align:center;
}
.v-marquee-inner span{
  height:50%;
}
.v-marquee-wrapper .v-marquee-block{
  width: 100%;
  height: 750px;
  overflow: hidden;
  box-sizing: border-box;
  position: relative;
  float:left;
}
.v-marquee-inner{
  display: block;
  height: 200%;
  width:100%;
  position: absolute;
}
.v-marquee-item p{
  font-weight: 800;
  font-size: 30px;
  padding:100px;
  font-family: cursive;
}
.v-marquee-inner.to-left{
  animation: v-marqueeTop 60s linear infinite;
}
.v-marquee-inner.to-right{
  animation: v-marqueeBottom 60s linear infinite;
}
.v-marquee-item{
  display: block;
  transition: all .1s ease-out;
  margin:20px 10px;
  box-shadow: rgba(0, 0, 0, 0.08) 0px 0px 14px 0px;
  border-radius:5px;
  -moz-border-radius:5px;
  -webkit-border-radius:5px;
  overflow: hidden;
}
.v-marquee-item img{
    width: 100%;
}

@keyframes v-marqueeTop{
  0% {
    top: 0;
  }
  100% {
    top: -500%;
  }
}
@keyframes v-marqueeBottom{
  0% { 
    top: -500%; 
  }
  100% {
   top: 0; 
  }
}


