/* image effect */


img.anim-up-down {
  -webkit-animation: move-up-down 1s infinite alternate;
  animation: move-up-down 1s infinite alternate;
}

img.anim-up-down {
  -webkit-animation: move-up-down 1s infinite alternate;
  animation: move-up-down 1s infinite alternate;
}

@-webkit-keyframes move-up-down {
  0% {
    transform: translateY(0);
  }

  100% {
    transform: translateY(-10px);
  }
}

@keyframes move-up-down {
  0% {
    transform: translateY(0);
  }

  100% {
    transform: translateY(-10px);
  }
}

