    margin-top: 2%;
    width: 70%;
    aspect-ratio: 1 / 0.4;
  
    border-top-right-radius: 11dvw;
    border-top-left-radius: 11dvw;
  
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    z-index: 1;
  
    position: relative;
    overflow: hidden;
  }
  
  #row1 {
    position: absolute;
    top: -65%;
    left: -10%;
    display: flex;
    justify-content: center;
    align-items: center;
  
    transform: rotate(-10deg);
  }
  
  
  #row2 {
    position: absolute;
    top: 18%;
    left: -10%;
    display: flex;
    justify-content: center;
    align-items: center;
  
    transform: rotate(-10deg);
  }
  
  .stack {
    display: flex;
    justify-content: center;
    align-items: center;
  
    animation: infiniteLeft 50s linear infinite;
  }
  
  .imagen {
  
    background-repeat: no-repeat;
    background-size: 100%;
    background-position: center;
  
    width: 23vw;
    aspect-ratio: 1 / 1;
    margin: 0.4%;
  
    border-radius: 2dvw;
    filter: blur(0.5px);
  }
  
  .reverse {
  
    animation: infiniteRight 50s linear infinite; 
    transform: translateX(-100%);
  
  }
  
  
  @keyframes infiniteLeft {
  
  
    0% {
  
      transform: translateX(0%);
    }
  
    100% {
  
      transform: translateX(-100%);
  
    }
  
  }
  
  @keyframes infiniteRight {
  
  
    0% {
  
      transform: translateX(-100%);
    }
  
    100% {
  
      transform: translateX(0%);
  
    }
  
  }


